import{_ as l,a0 as s,w as p,s as n,ao as u,I as o,x as r,a1 as a,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const c=JSON.parse('{"title":"如何让 KDE 看起来像 GNOME | LCTT x X-CMD","titleTemplate":false,"description":"如何让 KDE 看起来像 GNOME | LCTT (202202) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何让 KDE 看起来像 GNOME | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何让 KDE 看起来像 GNOME | LCTT (202202) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202202/20220222 How to make KDE look like GNOME on Linux","title":"如何让 KDE 看起来像 GNOME","tag":"202202","desc":""},"relativePath":"202202/20220222 How to make KDE look like GNOME on Linux.md","filePath":"[post].md"}'),d={name:"202202/20220222 How to make KDE look like GNOME on Linux.md"};function b(y,t,m,h,E,k){const e=s("Link");return p(),n("div",null,[t[15]||(t[15]=u('<h1 id="如何让-kde-看起来像-gnome" tabindex="-1">如何让 KDE 看起来像 GNOME <a class="header-anchor" href="#如何让-kde-看起来像-gnome" aria-label="Permalink to “如何让 KDE 看起来像 GNOME”">​</a></h1><blockquote><p>在不放弃你的 Plasma 桌面的情况下获得 GNOME 的感觉。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202202/28/121405fxmzdms3a4p4mspa.jpg" alt=""></p><p>GNOME 有一种极简主义设计的倾向。它是一种美丽的桌面体验，并且是第一个在我使用 Linux 时引起别人赞叹的自由桌面。然后（请原谅我的形而上的哲学思考），没有复杂性就没有极简主义，而 KDE 以其极具定制性而闻名。我认为测试一下 KDE 的配置可能会很有趣，并尝试在 KDE Plasma 桌面上重新实现，至少在表面上实现 GNOME 的体验。</p><p>如果你尝试这个，请在一个临时用户帐户中进行。这些变化相对来说比较剧烈，撤销它以回到你的标准 KDE 布局可能是一个很大的工作。</p><h3 id="adwaita-主题" tabindex="-1">Adwaita 主题 <a class="header-anchor" href="#adwaita-主题" aria-label="Permalink to “Adwaita 主题”">​</a></h3><p>GNOME 的默认主题叫做 Adwaita，是为 GTK 设计的，这是 GNOME 用于窗口和部件的工具包。KDE 使用 Qt 工具包，但 Fedora-Qt 项目已经开发了一个模仿 Adwaita 的 Qt 主题。这是在 KDE 上模仿 GNOME 的第一步，也是最明显的一步。使用你的发行版的包管理器安装 Adwaita for Qt：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install adwaita-qt{,5}</span></span></code></pre></div><p>在基于 Debian 的发行版上，请使用 <code>apt</code> 命令而不是 <code>dnf</code>。</p><p>安装完毕后，进入“<ruby>系统设置<rt>System Settings</rt></ruby>”，选择“<ruby>应用风格<rt>Application Style</rt></ruby>”。选择你喜欢的 Adwaita 主题变体：有一个浅色主题和一个深色主题，以及两者之间的变化。点击“<ruby>应用<rt>Apply</rt></ruby>”按钮来更新你的主题，但先不要关闭这个控制面板。</p><h3 id="窗口装饰" tabindex="-1">窗口装饰 <a class="header-anchor" href="#窗口装饰" aria-label="Permalink to “窗口装饰”">​</a></h3><p>在“<ruby>应用风格<rt>Application Style</rt></ruby>”窗口的左侧面板中选择“<ruby>窗口装饰<rt>Window Decorations</rt></ruby>”分类。如果有一个适合 Adwaita 的标题栏样式，通过选择它并点击“<ruby>应用<rt>Apply</rt></ruby>”来激活它。如果没有安装额外的装饰，点击面板右下方的“<ruby>获取新窗口装饰<rt>Get new window decorations</rt></ruby>”按钮，下载合适的东西。我使用了用户 x-varlesh-x 提供的 “Arc” 主题，但你可以四处看看，看看什么最适合你的其他主题。</p><p>GNOME 著名的是它的窗口标题栏上只有一个按钮，所以导航到“<ruby>标题栏按钮<rt>Titlebar Buttons</rt></ruby>”标签，然后通过将“<ruby>关闭<rt>Close</rt></ruby>”按钮从标题栏图像拖到处置区域来删除所有按钮。</p><p><img src="https://opensource.com/sites/default/files/kde-decoration-remove.jpg" alt="Removing buttons" title="Removing buttons"></p><p>取消选择“<ruby>显示标题栏按钮提示<rt>Show titlebar button tooltips</rt></ruby>”，因为 GNOME 不倾向于在系统部件上做提示。</p><p>点击“<ruby>应用<rt>Apply</rt></ruby>”来保存你的修改。</p><h3 id="gtk-主题" tabindex="-1">GTK 主题 <a class="header-anchor" href="#gtk-主题" aria-label="Permalink to “GTK 主题”">​</a></h3><p>在 KDE 上，使用 GTK 的应用通常会被重新主题化成与 KDE 的默认主题一致。现在你已经把你的主题从 KDE Breeze 改为 GNOME Adwaita，你必须告诉 GTK 使用 Adwaita 主题。</p><p>点击“<ruby>应用风格<rt>Application Style</rt></ruby>”面板底部的“<ruby>配置 GNOME/GTK 应用风格<rt>Configure GNOME/GTK application style</rt></ruby>”按钮，在下拉菜单中选择 “Adwaita”。</p><h3 id="工作区行为" tabindex="-1">工作区行为 <a class="header-anchor" href="#工作区行为" aria-label="Permalink to “工作区行为”">​</a></h3><p>GNOME 在视觉上比 KDE 更安静，所以在“<ruby>系统设置<rt>System Settings</rt></ruby>”中找到“<ruby>工作区行为<rt>Workspace behavior</rt></ruby>”面板，停用“<ruby>在鼠标悬停时显示信息提示<rt>Display informational tooltips on mouse hover</rt></ruby>”和“<ruby>显示状态变化的视觉反馈<rt>Display visual feedback for status changes</rt></ruby>”。</p><p>你也可以把打开文件和文件夹改为需要双击而不是单击（在实际中，这对我来说太不方便了）。</p><h3 id="图标和光标" tabindex="-1">图标和光标 <a class="header-anchor" href="#图标和光标" aria-label="Permalink to “图标和光标”">​</a></h3><p>你可以在“<ruby>系统设置<rt>System Settings</rt></ruby>”中把光标改为 Adwaita 主题，然后选择一个图标主题。我喜欢 Breeze 的图标，但它们确实感觉像 KDE。GNOME 使用 Adwaita 图标集，但由于它们是为 GNOME 设计的，所以缺少一些重要的 KDE 组件的图标。你可以点击“<ruby>图标<rt>Icons</rt></ruby>”控制面板中的“<ruby>获取新图标<rt>Get New Icons</rt></ruby>”按钮来浏览很多图标集，最后我选择了用户 alvatip 提供的 “Nordzy”。不过，有很多不错的图标集可用，查看它们，看看你喜欢什么。我发现任何不属于 Breeze 的东西都会使 KDE 看起来与我习惯的东西有足够的不同。</p><h3 id="系统面板" tabindex="-1">系统面板 <a class="header-anchor" href="#系统面板" aria-label="Permalink to “系统面板”">​</a></h3><p>GNOME 的面板在屏幕的顶部，而 KDE 的面板默认在屏幕的底部。GNOME 的面板在默认情况下也是比较空的，所以我发现最简单的做法是先把当前的 KDE 面板完全删除。</p><p>右键点击并选择“<ruby>编辑面板<rt>Edit panel</rt></ruby>”。进入编辑模式后，再次右键点击面板，选择“<ruby>删除面板<rt>Remove panel</rt></ruby>”。当它消失了，右击桌面上的任何地方，选择“<ruby>添加面板<rt>Add panel</rt></ruby>”并添加一个空面板。这样就在屏幕底部添加了一个面板，所以右击它，选择“<ruby>编辑面板<rt>Edit panel</rt></ruby>”，然后点击并拖动“<ruby>屏幕边缘<rt>Screen Edge</rt></ruby>”按钮到屏幕的顶部。</p><p>当仍处于编辑模式时，点击“<ruby>添加部件<rt>Add widgets</rt></ruby>”按钮，将“<ruby>应用仪表板<rt>Application dashboard</rt></ruby>”部件添加到面板的最左端。然后从“<ruby>编辑面板<rt>Edit panel</rt></ruby>”视图中添加一个“<ruby>间隔<rt>Spacer</rt></ruby>”块，然后是一个“<ruby>时钟<rt>Clock</rt></ruby>”，然后是另一个“<ruby>间隔<rt>Spacer</rt></ruby>”。你可以拖动这些小部件来排列它们，所以我发现最简单的做法是添加上应用仪表板和时钟，然后是两个间隔，再把它们排列起来。</p><p><img src="https://opensource.com/sites/default/files/kde-panel-edit.jpg" alt="Editing the panel" title="Editing the panel"></p><p>你可以右键点击每个小组件来定制图标和布局。例如，我把日期从时钟上移走了，因为它在附加了日期后看起来很挤，尽管 GNOME 确实包含了日期。</p><p>通过进入“<ruby>系统设置<rt>System Settings</rt></ruby>”，选择一个深色的 Plasma 主题，比如 “Breeze Dark”，将面板改为黑色。</p><h3 id="gnome-plasma-桌面" tabindex="-1">GNOME Plasma 桌面 <a class="header-anchor" href="#gnome-plasma-桌面" aria-label="Permalink to “GNOME Plasma 桌面”">​</a></h3><p>通过一些快速的调整，你的桌面现在在各个方面接近于 GNOME。布局是类似的。</p><p><img src="https://opensource.com/sites/default/files/kde-like-gnome_0.jpg" alt="GNOME layout" title="GNOME layout"></p><p>应用仪表板提供了一个 GNOME 风格的应用启动器。</p><p><img src="https://opensource.com/sites/default/files/kde-application-dashboard_0.jpg" alt="Application dashboard" title="Application dashboard"></p><p>其他小的修改进一步有助于产生这种错觉。例如，我简化了 Dolphin 文件管理器，去掉了“<ruby>位置<rt>Places</rt></ruby>”面板，也去掉了工具栏上的大部分按钮。</p><h3 id="一个不同的视角" tabindex="-1">一个不同的视角 <a class="header-anchor" href="#一个不同的视角" aria-label="Permalink to “一个不同的视角”">​</a></h3><p>这不是一个精确的匹配，比我更具钻研精神的人可以做的更多，得到更接近正确的结果。然而，像这样有趣的变化证明了 KDE 是多么的灵活，拥有大量的选项意味着你可以缩减你的交互内容以适应你的偏好。一个类似 GNOME 的桌面可以给你一个新的视角来看待你与桌面的互动，即使你不会永远保持这种布局，它可以帮助你发现你可能没有想到要寻找的选项。</p><hr>',40)),o("p",null,[t[1]||(t[1]=r("via: ",-1)),a(e,{href:"https://opensource.com/article/22/2/make-kde-look-like-gnome"},{default:i(()=>[...t[0]||(t[0]=[r("https://opensource.com/article/22/2/make-kde-look-like-gnome",-1)])]),_:1})]),o("p",null,[t[6]||(t[6]=r("作者：",-1)),a(e,{href:"https://opensource.com/users/seth"},{default:i(()=>[...t[2]||(t[2]=[r("Seth Kenlon",-1)])]),_:1}),t[7]||(t[7]=r(" 选题：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[3]||(t[3]=[r("lujun9972",-1)])]),_:1}),t[8]||(t[8]=r(" 译者：",-1)),a(e,{href:"https://github.com/geekpi"},{default:i(()=>[...t[4]||(t[4]=[r("geekpi",-1)])]),_:1}),t[9]||(t[9]=r(" 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:i(()=>[...t[5]||(t[5]=[r("wxy",-1)])]),_:1})]),o("p",null,[t[12]||(t[12]=r("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[10]||(t[10]=[r("LCTT",-1)])]),_:1}),t[13]||(t[13]=r(" 原创编译，",-1)),a(e,{href:"https://linux.cn/"},{default:i(()=>[...t[11]||(t[11]=[r("Linux中国",-1)])]),_:1}),t[14]||(t[14]=r(" 荣誉推出",-1))])])}const G=l(d,[["render",b]]);export{c as __pageData,G as default};
